from typing import List
from functools import lru_cache

class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        # Precompute adjacency: can we place i before j?
        ok = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    ok[i][j] = (nums[i] % nums[j] != 0) and (nums[j] % nums[i] != 0)

        @lru_cache(maxsize=None)
        def dp(last: int, mask: int) -> int:
            # Number of ways to build a permutation with `mask` used numbers, ending with `last`
            if mask == (1 << n) - 1:
                return 1
            total = 0
            for nxt in range(n):
                if not (mask & (1 << nxt)):
                    if last == -1 or ok[last][nxt]:
                        total += dp(nxt, mask | (1 << nxt))
            return total % MOD

        return dp(-1, 0)
